2297:   const inEl = document.getElementById('inPlanAmount');
2298:   const inputVal = inEl ? parseFloat(inEl.value) : NaN;
2299:   const amount = (isFinite(inputVal) && inputVal > 0) ? inputVal : PLAN_AMOUNT_DEFAULT;
2300:   $('#planHead').textContent = fmt(amount, 0) + ' 元 · 本次投入';
2301:   const body = $('#planBody'), note = $('#planNote');
2302:   const COLS = 9;
2303:   const hasMargin = rows.some(r => r.margin);
2304:   if (!amount) {
2305:     body.innerHTML = '<tr><td colspan="' + COLS + '" class="dim" style="text-align:center;padding:16px">请在上面填写本次投入金额，或让 config.js 给出 rules.monthly_capital。</td></tr>';
2306:     note.textContent = '';   // 清空金额时同步清 note，避免残留上一次的「本次买 X 只」
2307:     return;
2308:   }
2309:   if (!rows.length) {
2310:     body.innerHTML = '<tr><td colspan="' + COLS + '" class="dim" style="text-align:center;padding:16px">未配置目标池（先记一笔买入，或让 config.js 生成目标清单）。</td></tr>';
2311:     note.textContent = '买入推荐依赖 config.js 的目标权重；安全边际指标（股息率/分位/布林带）页面内实时计算，取不到时本轮不买。';
2312:     return;
2313:   }
2314:   const res = buildPlan(amount, rows, T);
