2316:   // 目标买价单元格（股息率绝对值阈值）：现价 <= 目标价 达标；#3 显示目标股息率构成
2317:   const tgtCell = r => {
2318:     const mg = r.margin;
2319:     if (!mg || !(mg.targetBuyAbsolute > 0)) return '<td class="num dim">—</td>';
2320:     const hit = r.buyToTgtPct != null && r.buyToTgtPct >= 0;
2321:     const constTxt = mg.targetYldConst ? ' title="目标股息率 = ' + esc(mg.targetYldConst) + '"' : '';
2322:     return '<td class="num"><b class="' + (hit ? 'gold' : '') + '">' + fmt(mg.targetBuyAbsolute, 2) + '</b>' +
2323:       '<small class="tx3"' + constTxt + '>/' + fmt(mg.targetYld, 1) + '%' +
