/** 买入推荐表头「目标买价」小字：统一展示目标股息率，避免每行重复 */
function planTargetHeader(rows) {
  const sub = document.getElementById('planThTgtSub');
  if (!sub) return;
  const ys = [];
  (rows || []).forEach(r => {
    const t = r.margin && r.margin.targetYld;
    if (t != null && isFinite(t)) ys.push(+t);
  });
  if (!ys.length) {
    sub.textContent = '股息率阈值';
    return;
  }
  const mn = Math.min.apply(null, ys);
  const mx = Math.max.apply(null, ys);
  sub.textContent = mn === mx
    ? '目标股息率 ' + fmt(mn, 1) + '%'
    : '目标股息率 ' + fmt(mn, 1) + '%～' + fmt(mx, 1) + '%';
}

