tool_input.old_string:
const res = buildPlan(amount, rows, T);

// 目标买价单元格（股息率绝对值阈值）：现价 <= 目标价 达标；#3 显示目标股息率构成
const tgtCell = r => {
  const mg = r.margin;
  if (!mg || !(mg.targetBuyAbsolute > 0)) return '<td class="num dim">—</td>';
  const hit = r.buyToTgtPct != null && r.buyToTgtPct >= 0;
  const constTxt = mg.targetYldConst ? ' title="目标股息率 = ' + esc(mg.targetYldConst) + '"' : '';
  return '<td class="num"><b class="' + (hit ? 'gold' : '') + '">' + fmt(mg.targetBuyAbsolute, 2) + '</b>' +
    '<small class="tx3"' + constTxt + '>/' + fmt(mg.targetYld, 1) + '%' +
    (mg.targetYldConst ? '（' + esc(mg.targetYldConst) + '）' : '') + '</small></td>';
};
// 距买点：现价低于目标价多少（正=已达标，可买；负=还差多少才跌到）
const distCell = r => {
  if (r.buyToTgtPct == null) return '<td class="num dim">—</td>';
  if (r.buyToTgtPct >= 0) return '<td class="num gold">达标 <small>+' + fmt(r.buyToTgtPct, 1) + '%</small></td>';
  // #9 分位高但未达标时加小字解释，避免「这么便宜为什么不能买」的困惑
  const hiPct = r.margin && r.margin.yldPct != null && r.margin.yldPct >= 80 && !r.pctSampleLow;
  const tip = hiPct ? '<br><small class="tx3" title="分位高=历史便宜，但当前股息率未达目标价，继续等目标价">分位高但未达标，等目标价</small>' : '';
  return '<td class="num dim">还差 ' + fmt(-r.buyToTgtPct, 1) + '%' + tip + '</td>';
};
// 股息率分位（近 3 年）：>=80 高安全边际；#8 样本不足 250 日显示「样本不足」
const pctCell = r => {
  const p = r.margin && r.margin.yldPct;
  if (p == null) return '<td class="num dim">—</td>';
  if (r.pctSampleLow) return '<td class="num tx3" title="样本 ' + (r.margin.histYldN || 0) + ' 日，不足一年，分位仅供参考不计分">样本不足<small>(' + (r.margin.histYldN || 0) + '日)</small></td>';
  const hi = p >= 80;
  return '<td class="num ' + (hi ? 'gold' : '') + '">' + fmt(p, 0) + '<small class="tx3">%位</small></td>';
};
// 布林带：显示 60 日下轨；触底标绿；#2 基本面越线时改提示
const bollCell = r => {
  const b = r.boll60 || r.boll20;
  if (!b) return '<td class="num dim">—</td>';
  if (b.belowLower && r.fundBreak)
    return '<td class="num tx3" title="跌破下轨但基本面越线，不构成买点">' + fmt(b.lower, 2) + '<small>跌破(基本面越线)</small></td>';
  return '<td class="num ' + (b.belowLower ? 'gold' : '') + '">' + fmt(b.lower, 2) +
    '<small class="tx3">' + (b.belowLower ? ' 触底' : ' ' + fmt(b.distToLowerPct, 1) + '%') + '</small></td>';
};

tool_input.new_string:
const res = buildPlan(amount, rows, T);
planTargetHeader(rows);

// 目标买价：表头已写目标股息率，格内只保留价格（hover 可见口径说明）
const tgtCell = r => {
  const mg = r.margin;
  if (!mg || !(mg.targetBuyAbsolute > 0)) return '<td class="num dim">—</td>';
  const hit = r.buyToTgtPct != null && r.buyToTgtPct >= 0;
  const tip = '目标价 ' + fmt(mg.targetBuyAbsolute, 2) + ' 元（目标股息率 ' + fmt(mg.targetYld, 1) + '%' +
    (mg.targetYldConst ? '，规则 ' + esc(mg.targetYldConst) : '') + '）';
  return '<td class="num" title="' + esc(tip) + '"><b class="' + (hit ? 'gold' : '') + '">' + fmt(mg.targetBuyAbsolute, 2) + '</b></td>';
};
// 距买点：正=安全垫（现价低于目标价）；负=需再跌多少到目标价
const distCell = r => {
  if (r.buyToTgtPct == null) return '<td class="num dim">—</td>';
  const tip = '相对目标买价：+' + fmt(r.buyToTgtPct, 2) + '%（正=现价低于目标价，安全垫；负=距目标价还差）';
  if (r.buyToTgtPct >= 0) {
    return '<td class="num g" title="' + esc(tip) + '">安全垫 <small>+' + fmt(r.buyToTgtPct, 1) + '%</small></td>';
  }
  const hiPct = r.margin && r.margin.yldPct != null && r.margin.yldPct >= 80 && !r.pctSampleLow;
  const tip2 = hiPct ? '分位高=历史股息便宜，但当前股息率未达目标价，继续等目标价' : '';
  const extra = hiPct ? '<br><small class="tx3" title="' + esc(tip2) + '">分位高但未达标，等目标价</small>' : '';
  return '<td class="num dim" title="' + esc(tip) + '">需跌 <small>' + fmt(-r.buyToTgtPct, 1) + '%</small>' + extra + '</td>';
};
// 股息率分位：弱化为辅助（高分的仅作提示，不与主决策抢色）
const pctCell = r => {
  const p = r.margin && r.margin.yldPct;
  if (p == null) return '<td class="num dim">—</td>';
  if (r.pctSampleLow)
    return '<td class="num pct-muted" title="样本 ' + (r.margin.histYldN || 0) + ' 日，不足一年，分位仅供参考不计分">样本不足<small class="tx3">(' + (r.margin.histYldN || 0) + '日)</small></td>';
  const hi = p >= 80;
  const tip = '近3年股息率分位 ' + fmt(p, 0) + '%（越高=相对历史越便宜；下单以绝对股息率与目标价为主）';
  const main = '<span class="tx3">' + fmt(p, 0) + '</span><small class="tx3">%位</small>' +
    (hi ? ' <span class="badge b-mut" title="高安全边际（辅助）">高</span>' : '');
  return '<td class="num pct-muted" title="' + esc(tip) + '">' + main + '</td>';
};
// 布林带：仅保留下轨数值 + 触底/跌破说明；不写「距下轨%」以免误解
const bollCell = r => {
  const b = r.boll60 || r.boll20;
  if (!b) return '<td class="num dim">—</td>';
  if (b.belowLower && r.fundBreak) {
    const tip = '跌破下轨但基本面越线，不构成买点';
    return '<td class="num tx3 boll-muted" title="' + esc(tip) + '"><b>' + fmt(b.lower, 2) + '</b><small>跌破·基本面越线</small></td>';
  }
  const tip = b.belowLower
    ? '现价≤布林下轨（辅助）；下单仍以股息率目标价为主'
    : '60/20 日布林下轨（辅助）；下轨 ' + fmt(b.lower, 2) + ' 元';
  const sub = b.belowLower
    ? '<small class="tx3">触底</small>'
    : '<small class="tx3" title="距下轨相对幅度，辅助">参考</small>';
  return '<td class="num boll-muted" title="' + esc(tip) + '"><b class="' + (b.belowLower ? 'gold' : '') + '">' + fmt(b.lower, 2) + '</b>' + sub + '</td>';
};
const afterCell = x => {
  const after = res.base > 0 ? (x.r.mv + x.cost) / res.base * 100 : 0;
  const cap = +x.r.capPct || 0;
  let cls = 'num';
  if (cap > 0) {
    if (after >= cap * 1.02) cls += ' after-bad';
    else if (after >= cap * 0.92) cls += ' after-warn';
  }
  return '<td class="' + cls + '">' + fmt(after, 2) + '% <span class="tx3">/' + fmt(x.r.capPct, 2) + '</span></td>';
};

