        : '距目标价还差 <b>' + fmt(-r.buyToTgtPct, 1) + '%</b>');
    }
    return '<b>' + esc(r.name) + '</b>：' + segs.join('，');
  });
  return '<div class="plan-line-reason pct-mute"><b>买入理由：</b>' + bits.join('；') + '。</div>';
})();
